using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using UnityEditor;
using UnityEditor.Compilation;
using UnityEngine;
[InitializeOnLoad]
public static class HolmesSourceRestConsumer {
 const string K="HOLMES1215_RUNNING", Done="HOLMES1215_IMPORTED", W="HOLMES1215_WORK";
 [Serializable] class Ref { public string guid,file_id; }
 [Serializable] class Group { public string topology; public int[] indices; }
 [Serializable] class Matrix { public float[] values; }
 [Serializable] class Influence {public int bone;public float weight; public int bits;}
 [Serializable] class Point {public Influence[] influences;}
 [Serializable] class Frame {public float weight;public Vector3[] delta_vertices,delta_normals,delta_tangents;}
 [Serializable] class Shape {public int index;public string label;public Frame[] frames;}
 static Shape[] Shapes(Mesh m){return Enumerable.Range(0,m.blendShapeCount).Select(i=>new Shape{index=i,label=m.GetBlendShapeName(i),frames=Enumerable.Range(0,m.GetBlendShapeFrameCount(i)).Select(j=>{var v=new Vector3[m.vertexCount];var n=new Vector3[m.vertexCount];var t=new Vector3[m.vertexCount];m.GetBlendShapeFrameVertices(i,j,v,n,t);return new Frame{weight=m.GetBlendShapeFrameWeight(i,j),delta_vertices=v,delta_normals=n,delta_tangents=t};}).ToArray()}).ToArray();}
 [Serializable] class Skin {public Matrix[] bone_world,bone_local;public Ref mesh,renderer,root,source_root;public Ref[] bones,bone_parents,materials,source_bones,source_parents;public Vector3[] vertices,normals;public Vector2[] uv;public Group[] groups;public Matrix[] bindposes;public Point[] weights;public float[] matrix;public int shapes;public Shape[] shape_data;public float[] shape_weights;public bool cloth; public string[] realization;}
 [Serializable] class Task {public string source_model_guid,model_guid,variant_path,kind;}
 [Serializable] class Manifest {public Task[] reference_rebind_tasks;}
 [Serializable] class Report {public string instruction_id="HOLMES-20261012-15",status="FAIL",error,unity_version,phase,package_sha256,finalizer_sha256;public Skin source,source_after,post_import,post_apply,variant;public bool apply,source_bytes_preserved,repeat_apply;public string[] rejection;public string[] guard_controls;public bool repeat_variant_bytes_unchanged,repeat_variant_meta_unchanged,repeat_variant_semantics_unchanged;}
 static string Arg(string key){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,key);return i<0?"":a[i+1];}
 static string Work=>SessionState.GetString(W,Arg("-freshWork"));
 static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 static Ref Id(UnityEngine.Object o){if(o==null)return null; if(!AssetDatabase.TryGetGUIDAndLocalFileIdentifier(o,out string g,out long id))throw new Exception("MissingIdentity");return new Ref{guid=g,file_id=id.ToString(System.Globalization.CultureInfo.InvariantCulture)};}
 static float[] M(Matrix4x4 m){return Enumerable.Range(0,16).Select(i=>m[i]).ToArray();}
 static Skin Capture(GameObject root){var s=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();var m=s.sharedMesh;var counts=m.GetBonesPerVertex();var weights=m.GetAllBoneWeights();int k=0;var points=new Point[counts.Length];try{for(int v=0;v<counts.Length;v++){var inf=new Influence[counts[v]];for(int j=0;j<inf.Length;j++){var q=weights[k++];inf[j]=new Influence{bone=q.boneIndex,weight=q.weight,bits=BitConverter.ToInt32(BitConverter.GetBytes(q.weight),0)};}points[v]=new Point{influences=inf};}}finally{counts.Dispose();weights.Dispose();}
 return new Skin{bone_world=s.bones.Select(b=>new Matrix{values=M(b.localToWorldMatrix)}).ToArray(),bone_local=s.bones.Select(b=>new Matrix{values=M(Matrix4x4.TRS(b.localPosition,b.localRotation,b.localScale))}).ToArray(),source_root=Id(PrefabUtility.GetCorrespondingObjectFromSource(s.rootBone)),source_bones=s.bones.Select(b=>Id(PrefabUtility.GetCorrespondingObjectFromSource(b))).ToArray(),source_parents=s.bones.Select(b=>Id(PrefabUtility.GetCorrespondingObjectFromSource(b.parent))).ToArray(),mesh=Id(m),renderer=Id(s),root=Id(s.rootBone),bones=s.bones.Select(Id).ToArray(),bone_parents=s.bones.Select(b=>Id(b.parent)).ToArray(),materials=s.sharedMaterials.Select(Id).ToArray(),vertices=m.vertices,normals=m.normals,uv=m.uv,groups=Enumerable.Range(0,m.subMeshCount).Select(i=>new Group{topology=m.GetTopology(i).ToString(),indices=m.GetIndices(i,true)}).ToArray(),bindposes=m.bindposes.Select(b=>new Matrix{values=M(b)}).ToArray(),weights=points,matrix=M(s.transform.localToWorldMatrix),shapes=m.blendShapeCount,shape_data=Shapes(m),shape_weights=Enumerable.Range(0,m.blendShapeCount).Select(s.GetBlendShapeWeight).ToArray(),cloth=s.GetComponent<Cloth>()!=null,realization=root.GetComponentsInChildren<Transform>(true).Select(t=>{var marker=t.GetComponents<Component>().FirstOrDefault(c=>c!=null&&c.GetType().Name=="VapbRealizationMarker");return marker==null?"":EditorJsonUtility.ToJson(marker);}).Where(x=>x!="").ToArray()}; }
 static HolmesSourceRestConsumer(){EditorApplication.update+=Wait;AssetDatabase.importPackageCompleted+=n=>SessionState.SetBool(Done,true);CompilationPipeline.assemblyCompilationFinished+=(a,m)=>{if(m.Any(x=>x.type==CompilerMessageType.Error))SessionState.SetBool("HOLMES1215_ERRORS",true);};AssemblyReloadEvents.afterAssemblyReload+=()=>SessionState.SetBool("HOLMES1215_RELOAD",true);}
 public static void Run(){SessionState.SetString(W,Arg("-freshWork"));SessionState.SetBool(K,true);SessionState.SetBool(Done,false);SessionState.SetBool("HOLMES1215_ERRORS",false);SessionState.SetBool("HOLMES1215_RELOAD",false);AssetDatabase.ImportPackage(Arg("-freshPackage"),false);}
 static void Wait(){if(!SessionState.GetBool(K,false)||!SessionState.GetBool(Done,false)||EditorApplication.isCompiling||EditorApplication.isUpdating)return;SessionState.SetBool(K,false);var r=new Report{unity_version=Application.unityVersion,phase=Arg("-freshPhase")};try{if(SessionState.GetBool("HOLMES1215_ERRORS",false))throw new Exception("CompileErrors");const string path="Assets/VAPBExport/manifest.json";var t=JsonUtility.FromJson<Manifest>(File.ReadAllText(path)).reference_rebind_tasks.Single();if(t.kind!="RESTORE_SOURCE_MODEL_SKIN_VARIANT_V1")throw new Exception("TaskKind");string src=AssetDatabase.GUIDToAssetPath(t.source_model_guid),edit=AssetDatabase.GUIDToAssetPath(t.model_guid);r.source=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(src));r.post_import=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(edit));string[] protectedPaths={src,src+".meta"};var hashes=protectedPaths.Select(Hash).ToArray();var errors=new System.Collections.Generic.List<string>();Application.LogCallback log=(msg,stack,type)=>{if(type==LogType.Error||type==LogType.Exception)errors.Add(msg);};Application.logMessageReceived+=log;var f=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("VapbModelSkinFinalizer")).Single(x=>x!=null);r.finalizer_sha256=Hash("Assets/VAPBExport/Editor/VapbModelSkinFinalizer.cs");r.apply=(bool)f.GetMethod("Apply").Invoke(null,new object[]{path});Application.logMessageReceived-=log;r.rejection=errors.ToArray();r.post_apply=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(edit));r.source_bytes_preserved=hashes.SequenceEqual(protectedPaths.Select(Hash));if(r.apply){r.variant=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(t.variant_path));string vh=Hash(t.variant_path),vm=Hash(t.variant_path+".meta"),sem=JsonUtility.ToJson(r.variant);r.repeat_apply=(bool)f.GetMethod("Apply").Invoke(null,new object[]{path});r.repeat_variant_bytes_unchanged=vh==Hash(t.variant_path);r.repeat_variant_meta_unchanged=vm==Hash(t.variant_path+".meta");r.repeat_variant_semantics_unchanged=sem==JsonUtility.ToJson(Capture(AssetDatabase.LoadAssetAtPath<GameObject>(t.variant_path)));}if(r.apply){HolmesSourceRestGeometry.Capture();r.guard_controls=HolmesRestControls.Run(f,path,t.variant_path,src,edit,Work);r.source_after=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(src));}r.package_sha256=Hash(Arg("-freshPackage"));r.status="OBSERVED";}catch(Exception e){r.error=e.ToString();}Finish(r);}
 public static void ObserveWeightCopy(string asset){string work=Arg("-freshWork");if(string.IsNullOrEmpty(work)||!asset.Contains("/WeightCheck_")||!asset.EndsWith("/Model.fbx"))return;var root=AssetDatabase.LoadAssetAtPath<GameObject>(asset);if(root==null)return;var skin=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();var uv=new System.Collections.Generic.List<Vector2>();skin.sharedMesh.GetUVs(1,uv);if(uv.Count==0)return;var receipts=skin.bones.Select(b=>{var c=b.GetComponents<Component>().Single(x=>x!=null&&x.GetType().Name=="VapbRealizationMarker");return (string)c.GetType().GetField("boneRealizationId").GetValue(c);}).ToArray();var record=new WeightObservation{skin=Capture(root),cp_marker=uv.ToArray(),bone_receipts=receipts,fbx_sha256=Hash(asset)};string name="weight-observation-"+Guid.NewGuid().ToString("N")+".json";File.WriteAllText(Path.Combine(work,name),JsonUtility.ToJson(record,true));}
 [Serializable] class WeightObservation{public Skin skin;public Vector2[] cp_marker;public string[] bone_receipts;public string fbx_sha256;}
 static void Finish(Report r){SessionState.SetBool(K,false);File.WriteAllText(Path.Combine(Work,"native.json"),JsonUtility.ToJson(r,true));EditorApplication.Exit(r.status=="FAIL"?1:0);}
}

public sealed class HolmesSourceRestWeightObserver:AssetPostprocessor{static void OnPostprocessAllAssets(string[] imported,string[] deleted,string[] moved,string[] movedFrom){foreach(string p in imported)HolmesSourceRestConsumer.ObserveWeightCopy(p);}}
